include 'includes/db.php';
$pageTitle='Partner With Us | Join CleanNora as a Service Professional';
$pageDescription='Login and apply to become a CleanNora service partner. Submit your profile and KYC documents for partner onboarding.';
$success=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['partner_apply'])){
$name=trim($_POST['name']??'');$phone=preg_replace('/\D+/','',$_POST['phone']??'');$email=trim($_POST['email']??'');$city=trim($_POST['city']??'');$area=trim($_POST['area']??'');$service=trim($_POST['service']??'');$experience=trim($_POST['experience']??'');
if($name===''||strlen($phone)<10||$city===''||$service===''){$error='Please complete all required fields.';}
else{
mysqli_query($conn,"CREATE TABLE IF NOT EXISTS partner_applications (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,email VARCHAR(160) NULL,city VARCHAR(100) NOT NULL,area VARCHAR(160) NULL,service VARCHAR(100) NOT NULL,experience VARCHAR(80) NULL,aadhaar_ref VARCHAR(255) NULL,pan_ref VARCHAR(255) NULL,photo_ref VARCHAR(255) NULL,status VARCHAR(30) DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
$stmt=mysqli_prepare($conn,"INSERT INTO partner_applications(name,phone,email,city,area,service,experience,status) VALUES(?,?,?,?,?,?,?,'new')");
if($stmt){mysqli_stmt_bind_param($stmt,'sssssss',$name,$phone,$email,$city,$area,$service,$experience);$success=mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);}if(!$success&&!$error)$error='Application could not be submitted. Please call +91 92050 80012.';
}}
include 'includes/header.php';?>
