<script type="module">
import{RecaptchaVerifier,signInWithPhoneNumber}from"https://www.gstatic.com/firebasejs/12.1.0/firebase-auth.js";
let confirmation=null;const msg=document.getElementById('pwLoginMsg');
document.getElementById('pwSendOtp')?.addEventListener('click',async()=>{try{const n=document.getElementById('pwPhone').value.replace(/\D/g,'');if(n.length!==10)throw new Error('Enter a valid 10-digit mobile number.');const auth=window.cleannoraFirebaseAuth;if(!auth)throw new Error('Login service is not ready.');if(!window.pwVerifier)window.pwVerifier=new RecaptchaVerifier(auth,'pwRecaptcha',{size:'normal'});confirmation=await signInWithPhoneNumber(auth,'+91'+n,window.pwVerifier);document.getElementById('pwOtpBox').style.display='block';msg.textContent='OTP sent.';}catch(e){msg.textContent=e.message||'Unable to send OTP.';}});
document.getElementById('pwVerifyOtp')?.addEventListener('click',async()=>{try{if(!confirmation)throw new Error('Send OTP first.');await confirmation.confirm(document.getElementById('pwOtp').value.trim());const n=document.getElementById('pwPhone').value.replace(/\D/g,'');document.getElementById('pwVerifiedPhone').value=n;document.getElementById('partnerLogin').style.display='none';document.getElementById('partnerForm').style.display='block';}catch(e){msg.textContent='Invalid OTP. Please try again.';}});
</script><?php include 'includes/footer.php';?>